        self.val = val
        self.left = self.right = None
    def insert(self, val):
        if val < self.val:
            if self.left: self.left.insert(val)
            else: self.left = BinaryTree(val)
        else:
            if self.right: self.right.insert(val)
            else: self.right = BinaryTree(val)

